import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import cn from 'classnames';

import BackIcon from 'assets/images/icons/back.svg?react';
import { CreatePostbackForm } from 'entities/Postback';
import { useMedia } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink, Page, PageTitle } from 'shared/ui';

import styles from './CreatePostback.module.scss';

interface ICreatePostbackProps extends HTMLAttributes<HTMLDivElement> {}

export const CreatePostback: FC<ICreatePostbackProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();

	return (
		<Page {...props} className={cn(className, styles.createSource)}>
			<PageTitle
				inlineComponent={
					<ButtonStyleLink
						size="small"
						variant="text"
						color="primary"
						icon={isMd ? <BackIcon /> : undefined}
						to={`/${EMainRoutes.TOOLS}/${EMainRoutes.POSTBACKS}`}>
						{!isMd ? t('Вернуться назад') : undefined}
					</ButtonStyleLink>
				}>
				{t('Создание Postback')}
			</PageTitle>

			<CreatePostbackForm className={styles.form} />
		</Page>
	);
};

export default CreatePostback;
